import {
  brands,
  buttonContract,
  buttonSizes,
  buttonVariants,
  densities,
  designLanguages,
  inputs,
} from '@atom63/ui-foundation'
import { Button, UIProvider } from '@atom63/ui-react'
import '@atom63/ui-react/styles.css'
import type { Meta, StoryObj } from '@storybook/react-vite'
import { EnvironmentShell, PreviewCard, ThemeMatrix } from '../story-probes'

const meta = {
  title: 'UI React/Button',
  component: Button,
  argTypes: {
    variant: {
      control: 'select',
      options: buttonVariants,
    },
    size: {
      control: 'select',
      options: buttonSizes,
    },
    loading: { control: 'boolean' },
    disabled: { control: 'boolean' },
    children: { control: 'text' },
  },
  args: {
    children: 'Continue',
    disabled: false,
    loading: false,
    size: 'md',
    variant: 'default',
  },
} satisfies Meta<typeof Button>

export default meta

type Story = StoryObj<typeof meta>

function PlusIcon() {
  return (
    <svg aria-hidden="true" viewBox="0 0 16 16">
      <path
        d="M8 3.25v9.5M3.25 8h9.5"
        fill="none"
        stroke="currentColor"
        strokeLinecap="round"
        strokeWidth="1.7"
      />
    </svg>
  )
}

export const Playground: Story = {
  render: args => (
    <EnvironmentShell>
      <Button {...args} />
    </EnvironmentShell>
  ),
}

export const Variants: Story = {
  render: () => (
    <EnvironmentShell>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.75rem' }}>
        {buttonVariants.map(variant => (
          <Button key={variant} variant={variant}>
            {variant}
          </Button>
        ))}
      </div>
    </EnvironmentShell>
  ),
}

/* The parity sweep added two media-facing variants — `overlay` (frosted, sits
   on light imagery) and `glass` (dark-glass, sits on busy or bright imagery).
   Both are meant to float over media, so they only read correctly against a
   backdrop; render them over an image scrim rather than a flat panel. */
export const OverMedia: Story = {
  render: () => (
    <EnvironmentShell>
      <div
        style={{
          alignItems: 'center',
          backgroundImage:
            'linear-gradient(135deg, oklch(72% 0.16 250), oklch(64% 0.2 320) 55%, oklch(58% 0.18 30))',
          borderRadius: '0.875rem',
          display: 'flex',
          flexWrap: 'wrap',
          gap: '0.75rem',
          minHeight: '7rem',
          padding: '1.5rem',
        }}
      >
        <Button variant="overlay">Overlay</Button>
        <Button variant="glass">Glass</Button>
        <Button aria-label="Add" size="icon" variant="glass">
          <PlusIcon />
        </Button>
      </div>
    </EnvironmentShell>
  ),
}

export const Sizes: Story = {
  render: () => (
    <EnvironmentShell>
      <div style={{ alignItems: 'center', display: 'flex', flexWrap: 'wrap', gap: '0.75rem' }}>
        {buttonSizes.map(size => (
          <Button aria-label={size.startsWith('icon') ? 'Add' : undefined} key={size} size={size}>
            {size.startsWith('icon') ? <PlusIcon /> : size}
          </Button>
        ))}
      </div>
    </EnvironmentShell>
  ),
}

/* Tile size — full-width, icon-over-label; the launcher / app-grid shape ported
   from the legacy @atom63/ui button. Composes with any variant, and the caption
   wraps + stays centered. */
export const Tile: Story = {
  render: () => (
    <EnvironmentShell>
      <div style={{ display: 'grid', gap: '0.75rem', gridTemplateColumns: 'repeat(3, 1fr)' }}>
        <Button size="tile" variant="outline">
          <PlusIcon />
          New
        </Button>
        <Button size="tile" variant="outline">
          <PlusIcon />
          Import
        </Button>
        <Button size="tile" variant="ghost">
          <PlusIcon />A longer tile caption that wraps
        </Button>
      </div>
    </EnvironmentShell>
  ),
}

export const States: Story = {
  render: () => (
    <EnvironmentShell>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.75rem' }}>
        <Button>Default</Button>
        <Button loading>Loading</Button>
        <Button disabled>Disabled</Button>
        <Button data-pressed="">Pressed</Button>
        <Button variant="outline">
          <PlusIcon />
          With icon
        </Button>
      </div>
    </EnvironmentShell>
  ),
}

/* Loading treatment across every variant. */
export const Loading: Story = {
  render: () => (
    <EnvironmentShell>
      <div style={{ display: 'grid', gap: '0.875rem' }}>
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.75rem' }}>
          {buttonVariants
            .filter(variant => variant !== 'overlay' && variant !== 'glass')
            .map(variant => (
              <Button key={variant} loading variant={variant}>
                {variant}
              </Button>
            ))}
        </div>
        <div
          style={{
            backgroundImage:
              'linear-gradient(135deg, oklch(72% 0.16 250), oklch(64% 0.2 320) 55%, oklch(58% 0.18 30))',
            borderRadius: '0.875rem',
            display: 'flex',
            flexWrap: 'wrap',
            gap: '0.75rem',
            padding: '1.25rem',
          }}
        >
          <Button loading variant="overlay">
            Overlay
          </Button>
          <Button loading variant="glass">
            Glass
          </Button>
          <Button aria-label="Add" loading size="icon" variant="glass">
            <PlusIcon />
          </Button>
        </div>
      </div>
    </EnvironmentShell>
  ),
}

export const EnvironmentMatrix: Story = {
  parameters: {
    layout: 'fullscreen',
  },
  render: () => (
    <div
      style={{
        display: 'grid',
        gap: '1rem',
        gridTemplateColumns: 'repeat(auto-fit, minmax(19rem, 1fr))',
        padding: '1rem',
      }}
    >
      {designLanguages.map(designLanguage =>
        densities.map(density =>
          inputs.map(input => (
            <UIProvider
              density={density}
              designLanguage={designLanguage}
              input={input}
              key={`${designLanguage}-${density}-${input}`}
              mode="light"
            >
              <PreviewCard label={`${designLanguage} / ${density} / ${input}`}>
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.75rem' }}>
                  <Button>Continue</Button>
                  <Button variant="ghost">Maybe</Button>
                  <Button variant="ghost">Cancel</Button>
                </div>
              </PreviewCard>
            </UIProvider>
          ))
        )
      )}
    </div>
  ),
}

export const Endpoints: Story = {
  render: () => (
    <div style={{ display: 'grid', gap: 12 }}>
      {[
        {
          label: 'Web',
          props: { density: 'comfortable', designLanguage: 'web', input: 'pointer' } as const,
        },
        {
          label: 'iOS touch',
          props: { density: 'comfortable', designLanguage: 'ios', input: 'touch' } as const,
        },
        {
          label: 'Compact extension',
          props: {
            density: 'compact',
            designLanguage: 'web',
            input: 'pointer',
            surface: 'n2',
          } as const,
        },
      ].map(endpoint => (
        <UIProvider key={endpoint.label} {...endpoint.props}>
          <div
            style={{
              alignItems: 'center',
              background: 'var(--a63-surface-panel)',
              borderRadius: 'var(--radius-lg)',
              color: 'var(--a63-text-primary)',
              display: 'flex',
              flexWrap: 'wrap',
              gap: '0.5rem',
              padding: '0.75rem',
            }}
          >
            <span style={{ color: 'var(--a63-text-secondary)', fontSize: 12, width: 112 }}>
              {endpoint.label}
            </span>
            <Button variant="primary">Primary</Button>
            <Button>Default</Button>
            <Button variant="outline">Outline</Button>
            <Button variant="ghost">Ghost</Button>
            <Button aria-label="Add" size="icon">
              <PlusIcon />
            </Button>
          </div>
        </UIProvider>
      ))}
    </div>
  ),
}

export const BrandRamps: Story = {
  render: () => (
    <div
      style={{
        display: 'grid',
        gap: '1rem',
        gridTemplateColumns: 'repeat(auto-fit, minmax(11rem, 1fr))',
      }}
    >
      {brands.map(brand => (
        <UIProvider brand={brand} key={brand} mode="light">
          <PreviewCard label={`brand / ${brand}`}>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.5rem' }}>
              <Button variant="primary">Primary</Button>
              <Button variant="outline">Outline</Button>
            </div>
          </PreviewCard>
        </UIProvider>
      ))}
    </div>
  ),
}

/* Theme probe — the four skins x light/dark via the shared ThemeMatrix. */
export const Themes: Story = {
  parameters: { layout: 'fullscreen' },
  render: () => (
    <ThemeMatrix>
      <div style={{ display: 'grid', gap: '0.5rem' }}>
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.5rem' }}>
          <Button variant="primary">Primary</Button>
          <Button>Default</Button>
          <Button variant="destructive">Delete</Button>
          <Button variant="outline">Outline</Button>
          <Button variant="ghost">Ghost</Button>
        </div>
        <div
          style={{
            backgroundImage: 'linear-gradient(135deg, oklch(70% 0.16 250), oklch(60% 0.2 320))',
            borderRadius: '0.625rem',
            display: 'flex',
            flexWrap: 'wrap',
            gap: '0.5rem',
            padding: '0.75rem',
          }}
        >
          <Button variant="overlay">Overlay</Button>
          <Button variant="glass">Glass</Button>
        </div>
      </div>
    </ThemeMatrix>
  ),
}

export const ContractMetadata: Story = {
  render: () => (
    <pre style={{ fontSize: 12, margin: 0, whiteSpace: 'pre-wrap' }}>
      {JSON.stringify(buttonContract, null, 2)}
    </pre>
  ),
}

import { buttonGroupContract, themes } from '@atom63/ui-foundation'
import {
  Button,
  ButtonGroup,
  ButtonGroupSeparator,
  ButtonGroupText,
  Input,
  UIProvider,
} from '@atom63/ui-react'
import '@atom63/ui-react/styles.css'
import type { Meta, StoryObj } from '@storybook/react-vite'

const meta = {
  title: 'UI React/ButtonGroup',
  component: ButtonGroup,
} satisfies Meta<typeof ButtonGroup>

export default meta
type Story = StoryObj<typeof meta>

export const Playground: Story = {
  render: () => (
    <ButtonGroup>
      <Button variant="secondary">Left</Button>
      <Button variant="secondary">Middle</Button>
      <Button variant="secondary">Right</Button>
    </ButtonGroup>
  ),
}

export const Vertical: Story = {
  render: () => (
    <ButtonGroup orientation="vertical">
      <Button variant="secondary">Top</Button>
      <Button variant="secondary">Middle</Button>
      <Button variant="secondary">Bottom</Button>
    </ButtonGroup>
  ),
}

/* A non-interactive text prefix welded to an action. */
export const WithText: Story = {
  render: () => (
    <ButtonGroup>
      <ButtonGroupText>https://</ButtonGroupText>
      <Button variant="secondary">Copy</Button>
    </ButtonGroup>
  ),
}

/* A separator dividing two runs of actions. */
export const WithSeparator: Story = {
  render: () => (
    <ButtonGroup>
      <Button variant="secondary">Cut</Button>
      <Button variant="secondary">Copy</Button>
      <ButtonGroupSeparator />
      <Button variant="secondary">Paste</Button>
    </ButtonGroup>
  ),
}

export const Sizes: Story = {
  render: () => (
    <div style={{ alignItems: 'flex-start', display: 'grid', gap: 12 }}>
      {(['xs', 'sm', 'default', 'lg', 'xl'] as const).map(size => (
        <ButtonGroup key={size} size={size}>
          <Button variant="secondary">One</Button>
          <Button variant="secondary">Two</Button>
          <Button variant="secondary">Three</Button>
        </ButtonGroup>
      ))}
    </div>
  ),
}

export const Themes: Story = {
  render: () => (
    <div style={{ display: 'grid', gap: 12 }}>
      {themes.map(theme =>
        (['light', 'dark'] as const).map(mode => (
          <UIProvider key={`${theme}-${mode}`} mode={mode} theme={theme}>
            <div
              style={{
                alignItems: 'center',
                background: 'var(--a63-surface-panel)',
                borderRadius: '0.75rem',
                color: 'var(--a63-text-primary)',
                display: 'flex',
                gap: 12,
                padding: '0.75rem',
              }}
            >
              <span style={{ fontSize: 12, color: 'var(--a63-text-secondary)', width: 96 }}>
                {theme} / {mode}
              </span>
              <ButtonGroup>
                <Button type="button" variant="secondary">
                  Cut
                </Button>
                <Button type="button" variant="secondary">
                  Copy
                </Button>
                <Button type="button" variant="secondary">
                  Paste
                </Button>
              </ButtonGroup>
              <ButtonGroup size="icon-sm">
                <Button aria-pressed type="button" variant="ghost">
                  On
                </Button>
                <Button type="button" variant="ghost">
                  Off
                </Button>
                <Button type="button" variant="ghost">
                  Off
                </Button>
              </ButtonGroup>
            </div>
          </UIProvider>
        ))
      )}
    </div>
  ),
}

/* Height parity — a group sits next to an Input at the same size; both resolve
   the same --a63-control-height ramp x density, so their heights line up. */
export const WithInput: Story = {
  render: () => (
    <div style={{ display: 'grid', gap: 16 }}>
      {(['default', 'sm', 'lg'] as const).map(size => (
        <div key={size} style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
          <span style={{ fontSize: 12, color: 'var(--a63-text-secondary)', width: 56 }}>
            {size}
          </span>
          <Input
            aria-label="Example text field"
            placeholder="Search…"
            size={size === 'default' ? 'md' : size}
            style={{ width: 180 }}
          />
          <ButtonGroup size={size}>
            <Button variant="secondary">Cut</Button>
            <Button variant="secondary">Copy</Button>
            <Button variant="secondary">Paste</Button>
          </ButtonGroup>
        </div>
      ))}
    </div>
  ),
}

/* The same welded action run reviewed against target host contexts. */
export const Endpoints: Story = {
  render: () => (
    <div style={{ display: 'grid', gap: 12 }}>
      {[
        {
          label: 'Web',
          props: { density: 'comfortable', designLanguage: 'web', input: 'pointer' } as const,
        },
        {
          label: 'iOS touch',
          props: { density: 'comfortable', designLanguage: 'ios', input: 'touch' } as const,
        },
        {
          label: 'Compact extension',
          props: {
            density: 'compact',
            designLanguage: 'web',
            input: 'pointer',
            surface: 'n2',
          } as const,
        },
      ].map(endpoint => (
        <UIProvider key={endpoint.label} {...endpoint.props}>
          <div
            style={{
              alignItems: 'center',
              background: 'var(--a63-surface-panel)',
              borderRadius: 'var(--radius-lg)',
              color: 'var(--a63-text-primary)',
              display: 'flex',
              gap: 12,
              padding: '0.75rem',
            }}
          >
            <span style={{ fontSize: 12, color: 'var(--a63-text-secondary)', width: 112 }}>
              {endpoint.label}
            </span>
            <ButtonGroup size={endpoint.label === 'Compact extension' ? 'sm' : 'default'}>
              <Button variant="secondary">Cut</Button>
              <Button variant="secondary">Copy</Button>
              <Button variant="secondary">Paste</Button>
            </ButtonGroup>
            <ButtonGroup size={endpoint.label === 'Compact extension' ? 'sm' : 'default'}>
              <Button variant="ghost">Bold</Button>
              <Button variant="ghost">Italic</Button>
              <Button variant="ghost">Under</Button>
            </ButtonGroup>
          </div>
        </UIProvider>
      ))}
    </div>
  ),
}

export const ContractMetadata: Story = {
  render: () => (
    <pre style={{ fontSize: 12, margin: 0, whiteSpace: 'pre-wrap' }}>
      {JSON.stringify(buttonGroupContract, null, 2)}
    </pre>
  ),
}

import {
  copyButtonContract,
  copyButtonSizePairs,
  copyButtonSizes,
  themes,
} from '@atom63/ui-foundation'
import { CopyButton, UIProvider } from '@atom63/ui-react'
import '@atom63/ui-react/styles.css'
import type { Meta, StoryObj } from '@storybook/react-vite'
import { Toaster } from 'sonner'

const meta = {
  title: 'UI React/CopyButton',
  component: CopyButton,
  argTypes: {
    variant: { control: 'inline-radio', options: ['ghost', 'outline', 'secondary'] },
    size: { control: 'select', options: copyButtonSizes },
  },
  args: { value: 'npm i @atom63/ui-react', label: 'Command' },
  // sonner's Toaster so the success/error toast is visible in the canvas.
  decorators: [
    Story => (
      <>
        <Story />
        <Toaster />
      </>
    ),
  ],
} satisfies Meta<typeof CopyButton>

export default meta
type Story = StoryObj<typeof meta>

/* The visible value makes the icon-only action and its copied feedback unambiguous. */
export const Playground: Story = {
  render: args => (
    <div
      style={{
        alignItems: 'center',
        display: 'flex',
        gap: 8,
        maxWidth: '100%',
        padding: 8,
      }}
    >
      <code
        style={{
          minWidth: 0,
          overflow: 'hidden',
          textOverflow: 'ellipsis',
          whiteSpace: 'nowrap',
        }}
      >
        {args.value}
      </code>
      <CopyButton {...args} />
    </div>
  ),
}

/* With children the button widens and shows a "Copied!" label after the swap. */
export const WithLabel: Story = {
  args: { children: 'Copy command' },
}

/* Every icon-only size beside its equivalent icon + label size. */
export const Sizes: Story = {
  render: () => (
    <div style={{ display: 'grid', gap: 8 }}>
      {copyButtonSizePairs.map(pair => (
        <div
          key={pair.icon}
          style={{ alignItems: 'center', display: 'flex', gap: 12, minHeight: 48 }}
        >
          <span style={{ fontSize: 12, color: 'var(--a63-text-secondary)', width: 88 }}>
            {pair.icon} / {pair.label}
          </span>
          <CopyButton size={pair.icon} value={pair.icon} variant="outline" />
          <CopyButton size={pair.label} value={pair.label} variant="outline">
            Copy
          </CopyButton>
        </div>
      ))}
    </div>
  ),
}

/* The three supported variants (ghost / outline / secondary). */
export const Variants: Story = {
  render: () => (
    <div style={{ alignItems: 'center', display: 'flex', gap: 12 }}>
      <CopyButton value="ghost" variant="ghost" />
      <CopyButton value="outline" variant="outline" />
      <CopyButton value="secondary" variant="secondary" />
    </div>
  ),
}

/* Every DS theme × light/dark, showing all three variants on a panel. */
export const Themes: Story = {
  render: () => (
    <div style={{ display: 'grid', gap: 12 }}>
      {themes.map(theme =>
        (['light', 'dark'] as const).map(mode => (
          <UIProvider key={`${theme}-${mode}`} mode={mode} theme={theme}>
            <div
              style={{
                alignItems: 'center',
                background: 'var(--a63-surface-panel)',
                borderRadius: '0.75rem',
                color: 'var(--a63-text-primary)',
                display: 'flex',
                flexWrap: 'wrap',
                gap: 12,
                padding: '0.75rem',
              }}
            >
              <span style={{ fontSize: 12, color: 'var(--a63-text-secondary)', width: 96 }}>
                {theme} / {mode}
              </span>
              <CopyButton value="ghost" variant="ghost" />
              <CopyButton value="outline" variant="outline" />
              <CopyButton value="secondary" variant="secondary" />
              <CopyButton value="labelled" variant="outline">
                Copy
              </CopyButton>
            </div>
          </UIProvider>
        ))
      )}
    </div>
  ),
}

export const Endpoints: Story = {
  render: () => (
    <div style={{ display: 'grid', gap: 12 }}>
      {[
        {
          label: 'Web',
          props: { density: 'comfortable', designLanguage: 'web', input: 'pointer' } as const,
        },
        {
          label: 'iOS touch',
          props: { density: 'comfortable', designLanguage: 'ios', input: 'touch' } as const,
        },
        {
          label: 'Compact extension',
          props: { density: 'compact', designLanguage: 'web', input: 'pointer' } as const,
        },
      ].map(endpoint => (
        <UIProvider key={endpoint.label} {...endpoint.props}>
          <div
            style={{
              alignItems: 'center',
              background: 'var(--a63-surface-panel)',
              borderRadius: 'var(--radius-lg)',
              color: 'var(--a63-text-primary)',
              display: 'flex',
              gap: 12,
              padding: '0.75rem',
            }}
          >
            <span style={{ fontSize: 12, color: 'var(--a63-text-secondary)', width: 112 }}>
              {endpoint.label}
            </span>
            <CopyButton value={`${endpoint.label}-icon`} variant="outline" />
            <CopyButton value={`${endpoint.label}-label`} variant="outline">
              Copy
            </CopyButton>
          </div>
        </UIProvider>
      ))}
    </div>
  ),
}

export const ContractMetadata: Story = {
  render: () => (
    <pre style={{ fontSize: 12, margin: 0, whiteSpace: 'pre-wrap' }}>
      {JSON.stringify(copyButtonContract, null, 2)}
    </pre>
  ),
}

import { DestinationIndicator, DestinationLink } from '@atom63/ui-react'
import type { Meta, StoryObj } from '@storybook/react-vite'

const meta = {
  title: 'UI React/Destination Link',
  component: DestinationLink,
} satisfies Meta<typeof DestinationLink>

export default meta
type Story = StoryObj<typeof meta>

export const Internal: Story = {
  args: {
    children: (
      <>
        View project
        <DestinationIndicator className="size-4" kind="internal" />
      </>
    ),
    href: '#internal',
    kind: 'internal',
  },
}

export const External: Story = {
  args: {
    children: (
      <>
        View source
        <DestinationIndicator className="size-4" kind="external" />
      </>
    ),
    href: 'https://example.com',
    kind: 'external',
  },
}

/* Internal in dark mode, so visual regression covers dark for this component,
   which has no Themes matrix. The global applies to <html>, so portals are dark too. */
export const Dark: Story = { ...Internal, globals: { mode: 'dark' } }

import { autocompleteContract, themes } from '@atom63/ui-foundation'
import {
  Autocomplete,
  AutocompleteEmpty,
  AutocompleteGroup,
  AutocompleteGroupLabel,
  AutocompleteInput,
  AutocompleteItem,
  AutocompleteList,
  AutocompletePopup,
  AutocompleteSeparator,
  UIProvider,
} from '@atom63/ui-react'
import '@atom63/ui-react/styles.css'
import type { Meta, StoryObj } from '@storybook/react-vite'

const meta = {
  title: 'UI React/Autocomplete',
  component: Autocomplete,
  decorators: [
    Story => (
      <div style={{ padding: 'clamp(12px, 8vw, 48px)', width: 'min(320px, 100%)' }}>
        <Story />
      </div>
    ),
  ],
} satisfies Meta<typeof Autocomplete>

export default meta
type Story = StoryObj<typeof meta>

const fruits = [
  'Apple',
  'Apricot',
  'Banana',
  'Blackberry',
  'Blueberry',
  'Cherry',
  'Grape',
  'Mango',
  'Orange',
  'Peach',
]

const groupedFruits = {
  Recent: ['Apple', 'Banana', 'Cherry'],
  Citrus: ['Grapefruit', 'Lemon', 'Orange'],
  Berries: ['Blackberry', 'Blueberry', 'Strawberry'],
}

function Demo({ size }: { size?: 'sm' | 'default' | 'lg' | number }) {
  return (
    <Autocomplete items={fruits}>
      <AutocompleteInput placeholder="Search fruit…" showClear showTrigger size={size} />
      <AutocompletePopup>
        <AutocompleteEmpty>No fruit found.</AutocompleteEmpty>
        <AutocompleteList>
          {(fruit: string) => <AutocompleteItem key={fruit}>{fruit}</AutocompleteItem>}
        </AutocompleteList>
      </AutocompletePopup>
    </Autocomplete>
  )
}

function GroupedDemo({ size }: { size?: 'sm' | 'default' | 'lg' }) {
  return (
    <Autocomplete items={Object.values(groupedFruits).flat()}>
      <AutocompleteInput placeholder="Search fruit…" showClear showTrigger size={size} />
      <AutocompletePopup>
        <AutocompleteEmpty>No fruit found.</AutocompleteEmpty>
        <AutocompleteList>
          {Object.entries(groupedFruits).map(([group, values], index) => (
            <AutocompleteGroup key={group}>
              {index > 0 ? <AutocompleteSeparator /> : null}
