function Row({ children }: { children: ReactNode }) {
  return <div style={{ alignItems: 'center', display: 'flex', gap: '0.75rem' }}>{children}</div>
}

function EnvironmentShell({ children }: { children: ReactNode }) {
  return (
    <div
      style={{
