/** Busy backdrop, so the blur ramp is actually visible. */
const CHECKS =
  'repeating-conic-gradient(#e11d48 0% 25%, #0ea5e9 0% 50%) 50% / 24px 24px, linear-gradient(120deg, #f59e0b, #10b981)'

