        {children}
        <p
          style={{
            position: 'absolute',
            insetInline: 0,
            bottom: 0,
            zIndex: 30,
            margin: 0,
            padding: '14px',
            color: '#fff',
            font: '500 15px/1.35 system-ui, sans-serif',
          }}
        >
          Text over a busy image
        </p>
      </div>
      <figcaption style={{ font: '400 12px/1.4 system-ui, sans-serif', opacity: 0.7 }}>
        {label}
      </figcaption>
    </figure>
  )
}

